--   ('0dd3de90-10fc-485b-a961-343b01a84cee'::uuid, $l2n${"title":"Ecrire un grand nombre entier avec des espaces","description":"Jusqu'à 10 chiffres","variations":[{"blanks":[{"prefilled":"expression","removeSpaces":true,"expectedAnswer":"expression"}],"statement":"Réécris en espaçant correctement les chiffres.\n\n$$?$$","variables":[{"name":"a","expression":"4..10"},{"name":"expression","expression":"digits:a"}],"correction":{"steps":["**Écrire un grand nombre.** On sépare les chiffres par groupes de trois **en partant de la droite** (des unités) : classe des unités, classe des milliers, classe des millions, classe des milliards. Le groupe de gauche peut avoir un, deux ou trois chiffres.","On part du chiffre des unités de ${{expression}}$ et on compte les chiffres trois par trois vers la gauche ; on laisse un espace entre deux groupes.","$$\\begin{align} {{expression}} &= {{if:a>12|{{eval:floor(round(floor(expression/1000000000)-1000*floor(expression/1000000000000))/100)}}{{eval:mod((floor(round(floor(expression/1000000000)-1000*floor(expression/1000000000000))/10)),10)}}{{eval:mod((round(floor(expression/1000000000)-1000*floor(expression/1000000000000))),10)}}\\,|{{if:a>9|{{eval:round(floor(expression/1000000000)-1000*floor(expression/1000000000000))}}\\,|}}}}{{if:a>9|{{eval:floor(round(floor(expression/1000000)-1000*floor(expression/1000000000))/100)}}{{eval:mod((floor(round(floor(expression/1000000)-1000*floor(expression/1000000000))/10)),10)}}{{eval:mod((round(floor(expression/1000000)-1000*floor(expression/1000000000))),10)}}\\,|{{if:a>6|{{eval:round(floor(expression/1000000)-1000*floor(expression/1000000000))}}\\,|}}}}{{if:a>6|{{eval:floor(round(floor(expression/1000)-1000*floor(expression/1000000))/100)}}{{eval:mod((floor(round(floor(expression/1000)-1000*floor(expression/1000000))/10)),10)}}{{eval:mod((round(floor(expression/1000)-1000*floor(expression/1000000))),10)}}\\,|{{if:a>3|{{eval:round(floor(expression/1000)-1000*floor(expression/1000000))}}\\,|}}}}{{if:a>3|\\textcolor{{{color:primary.0}}}{{{eval:floor(round(expression-1000*floor(expression/1000))/100)}}{{eval:mod((floor(round(expression-1000*floor(expression/1000))/10)),10)}}{{eval:mod((round(expression-1000*floor(expression/1000))),10)}}}|{{if:a>0|\\textcolor{{{color:primary.0}}}{{{eval:round(expression-1000*floor(expression/1000))}}}|}}}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["1\\,234\\,567\\,890"],"expected":{"status":"correct"},"variables":{"a":"10","expression":"1234567890"},"description":"10 chiffres bien espacés (borne haute)","variationIndex":0},{"answers":["1234567890"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"10","expression":"1234567890"},"description":"10 chiffres sans espace","variationIndex":0},{"answers":["1\\,234\\,567\\,891"],"expected":{"status":"incorrect"},"variables":{"a":"10","expression":"1234567890"},"description":"chiffre modifié","variationIndex":0},{"answers":["5\\,000"],"expected":{"status":"correct"},"variables":{"a":"4","expression":"5000"},"description":"4 chiffres (borne basse)","variationIndex":0},{"answers":["5000"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"4","expression":"5000"},"description":"4 chiffres sans espace","variationIndex":0}]}$l2n$::jsonb),
--   ('11607586-7b7b-404f-8e62-91ddefa75efa'::uuid, $l2n${"title":"Factoriser","description":"Le plus grand facteur commun n'est pas apparent","variations":[{"blanks":[{"expectedAnswer":"{{a}}({{b}}{{f}}+{{c}}{{d}})"}],"statement":"Factorise le plus possible :\n\n$${{expression1}}$$","variables":[{"name":"expression1","expression":"{{eval:a*b}}{{f}}+{{eval:a*c}}{{d}}"}],"correction":{"steps":["$$\\begin{align}                 {{eval:a*b}}{{f}}+{{eval:a*c}}{{d}}               &= \\textcolor{{{color:primary.0}}}{{{a}}} \\times {{b}}{{f}} + \\textcolor{{{color:primary.0}}}{{{a}}} \\times {{c}}{{d}} \\\\               &= \\textcolor{{{color:primary.0}}}{{{a}}} \\times ({{b}}{{f}} + {{c}}{{d}}) \\\\               &= {{solution}}                \\end{align}$$"]}},{"blanks":[{"expectedAnswer":"{{a}}({{b}}{{f}}-{{c}}{{d}})"}],"statement":"Factorise le plus possible :\n\n$${{expression2}}$$","variables":[{"name":"expression2","expression":"{{eval:a*b}}{{f}}-{{eval:a*c}}{{d}}"}],"correction":{"steps":["$$\\begin{align}                 {{eval:a*b}}{{f}} - {{eval:a*c}}{{d}}               &= \\textcolor{{{color:primary.0}}}{{{a}}} \\times {{b}}{{f}} - \\textcolor{{{color:primary.0}}}{{{a}}} \\times {{c}}{{d}} \\\\               &= \\textcolor{{{color:primary.0}}}{{{a}}} \\times ({{b}}{{f}} - {{c}}{{d}}) \\\\               &= {{solution}}                \\end{align}$$"]}},{"blanks":[{"expectedAnswer":"{{a}}({{b}}{{f}}+{{c}})"}],"statement":"Factorise le plus possible :\n\n$${{expression3}}$$","variables":[{"name":"expression3","expression":"{{eval:a*b}}{{f}}+{{eval:a*c}}"}],"correction":{"steps":["$$\\begin{align}                 {{eval:a*b}}{{f}}+{{eval:a*c}}               &= \\textcolor{{{color:primary.0}}}{{{a}}} \\times {{b}}{{f}} + \\textcolor{{{color:primary.0}}}{{{a}}} \\times {{c}} \\\\               &= \\textcolor{{{color:primary.0}}}{{{a}}} \\times ({{b}}{{f}} + {{c}}) \\\\               &= {{solution}}                \\end{align}$$"]}},{"blanks":[{"expectedAnswer":"{{a}}({{b}}{{f}}-{{c}})"}],"statement":"Factorise le plus possible :\n\n$${{expression4}}$$","variables":[{"name":"expression4","expression":"{{eval:a*b}}{{f}}-{{eval:a*c}}"}],"correction":{"steps":["$$\\begin{align}                 {{eval:a*b}}{{f}}-{{eval:a*c}}               &= \\textcolor{{{color:primary.0}}}{{{a}}} \\times {{b}}{{f}} - \\textcolor{{{color:primary.0}}}{{{a}}} \\times {{c}} \\\\               &= \\textcolor{{{color:primary.0}}}{{{a}}} \\times ({{b}}{{f}} - {{c}}) \\\\               &= {{solution}}                \\end{align}$$"]}}],"shared":{"variables":[{"name":"a","expression":"2..9"},{"name":"b","expression":"2..9"},{"name":"c","expression":"2..9!cd(b)"},{"name":"d","expression":"x|y|z"},{"name":"f","expression":"x|y|z!d"}]},"test_specs":[{"answers":["7(9x+4y)"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"4","d":"y|y","f":"x|x"},"description":"v0 bonne réponse","variationIndex":0},{"answers":["7(9x-4y)"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"4","d":"y|y","f":"x|x"},"description":"v1 bonne réponse","variationIndex":1},{"answers":["7(9x+4)"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"4","d":"y|y","f":"x|x"},"description":"v2 bonne réponse","variationIndex":2},{"answers":["7(9x-4)"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"4","d":"y|y","f":"x|x"},"description":"v3 bonne réponse","variationIndex":3},{"answers":["2(12x+9)"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"6","b":"4","c":"3","d":"y|y","f":"x|x"},"description":"factorisation partielle 2(12x+9)","variationIndex":2},{"answers":["63x+28y"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"7","b":"9","c":"4","d":"y|y","f":"x|x"},"description":"non factorisé","variationIndex":0},{"answers":["6(4x+3)"],"expected":{"status":"correct"},"variables":{"a":"6","b":"4","c":"3","d":"y|y","f":"x|x"},"description":"6(4x+3)","variationIndex":2}]}$l2n$::jsonb),
--   ('201b17f0-a12e-4772-abc4-fe75cb81ef44'::uuid, $l2n${"title":"Calculer une différence (résultat positif)","description":"Soustraire des dizaines entières à un nombre","variations":[{"blanks":[{"expectedAnswer":"eval:expression"}],"statement":"$${{expression}}$$","variables":[{"name":"a","expression":"1..8"},{"name":"b","expression":"{{eval:a+1}}..9"},{"name":"c","expression":"0..9"},{"name":"expression","expression":"{{eval:b*10+c}}-{{eval:a*10}}"}],"correction":{"steps":["**Retrancher des dizaines entières.** On retranche ${{eval:a*10}}$, c'est-à-dire ${{eval:((a*10))/10}}$ {{if:((a*10))=10|dizaine|dizaines}} : {{if:(mod(((b*10+c)),10))*((b*10+c)-mod(((b*10+c)),10))>0|on met de côté $\\textcolor{{{color:primary.0}}}{{{eval:mod(((b*10+c)),10)}}}$ et on calcule $\\textcolor{{{color:primary.0}}}{{{eval:(b*10+c)-mod(((b*10+c)),10)}}} - {{eval:a*10}} = \\textcolor{{{color:primary.1}}}{{{eval:(b*10+c)-mod(((b*10+c)),10)-(a*10)}}}$.|on compte en dizaines.}}","$$\\begin{align} {{eval:b*10+c}} - {{eval:a*10}} &= {{if:(mod(((b*10+c)),10))*((b*10+c)-mod(((b*10+c)),10))>0|\\textcolor{{{color:primary.0}}}{{{eval:(b*10+c)-mod(((b*10+c)),10)}}} - {{eval:a*10}} + \\textcolor{{{color:primary.0}}}{{{eval:mod(((b*10+c)),10)}}} \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:(b*10+c)-mod(((b*10+c)),10)-(a*10)}}} + {{eval:mod(((b*10+c)),10)}} \\\\ &= |}}{{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["32"],"expected":{"status":"correct"},"variables":{"a":"4","b":"7","c":"2"},"description":"correct","variationIndex":0},{"answers":["33"],"expected":{"status":"incorrect"},"variables":{"a":"4","b":"7","c":"2"},"description":"incorrect","variationIndex":0},{"answers":["72-40"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"4","b":"7","c":"2"},"description":"bad form","variationIndex":0},{"answers":["032"],"expected":{"status":"unoptimal_form","constraintViolations":["zeros"]},"variables":{"a":"4","b":"7","c":"2"},"description