--   ('3bbe92f2-84f0-487f-9ca1-2077248a313b'::uuid, $l2n${"title":"Calculer une somme","description":"Partie entière et partie décimale à $1$ chiffre (pas de retenue)","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}};d}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"1..8"},{"name":"b","expression":"1..8"},{"name":"c","expression":"a.b"},{"name":"d","expression":"1..{{eval:9-a}}"},{"name":"f","expression":"1..{{eval:9-b}}"},{"name":"g","expression":"d.f"},{"name":"expression1","expression":"c+g"}],"correction":{"steps":["**Additionner des décimaux.** On additionne rang par rang : les unités avec les unités, les dixièmes avec les dixièmes, les centièmes avec les centièmes. $10$ dixièmes font $1$ unité.","Unités : $\\textcolor{{{color:primary.0}}}{{{a}}} + \\textcolor{{{color:primary.0}}}{{{d}}} = {{eval:a+d}}$. Dixièmes : $\\textcolor{{{color:primary.0}}}{{{b}}} + \\textcolor{{{color:primary.0}}}{{{f}}} = {{eval:b+f}}$ dixièmes{{if:b+f>=10|, soit $\\textcolor{{{color:primary.1}}}{1}$ unité et ${{eval:b+f-10}}$ dixième{{if:b+f-10>1|s|}}|}}.","$$\\begin{align} {{c}} + {{g}} &= \\left( \\textcolor{{{color:primary.0}}}{{{a}}} + \\textcolor{{{color:primary.0}}}{{{d}}} \\right) + \\left( \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} + \\textcolor{{{color:primary.0}}}{{{eval:f/10;d}}} \\right) \\\\ &= {{eval:a+d}} + \\textcolor{{{color:primary.1}}}{{{eval:(b+f)/10;d}}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["8{,}9"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"2","f":"1"},"description":"6,8 + 2,1 = 8,9","variationIndex":0},{"answers":["8.9"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"2","f":"1"},"description":"8.9 au point","variationIndex":0},{"answers":["8{,}8"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"8","d":"2","f":"1"},"description":"erreur : 8,8","variationIndex":0},{"answers":["89"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"8","d":"2","f":"1"},"description":"réponse 89 (virgule oubliée)","variationIndex":0}]}$l2n$::jsonb),
--   ('45e06ece-246e-4182-ae1f-8d04a98e6aae'::uuid, $l2n${"title":"Compléter une division à trou","description":"Diviser par $10$, $100$ ou $1000$","variations":[{"blanks":[{"expectedAnswer":"{{b}}"}],"statement":"Complète.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"1..3"},{"name":"m","expression":"0..4"},{"name":"q","expression":"0..4-a"},{"name":"b","expression":"digits:m.q"},{"name":"expression1","expression":"?:{{eval:10^a}}={{eval:b:10^a;d}}"}],"correction":{"steps":["$? : \\textcolor{{{color:primary.0}}}{{{eval:10^a}}} = {{eval:b:10^a;d}}$. On cherche le nombre qui, divisé par $\\textcolor{{{color:primary.0}}}{{{eval:10^a}}}$, donne ${{eval:b:10^a;d}}$. La division et la multiplication sont des opérations inverses : on $\\textcolor{{{color:primary.1}}}{\\text{multiplie}}$ ${{eval:b:10^a;d}}$ par $\\textcolor{{{color:primary.0}}}{{{eval:10^a}}}$.","$$\\begin{align} ? &= {{eval:b:10^a;d}} \\textcolor{{{color:primary.1}}}{\\times} \\textcolor{{{color:primary.0}}}{{{eval:10^a}}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":{"conditions":["q<=4-a","b!=0","mod(b*10^q,10)!=0","b>=10^(m-1)"]},"test_specs":[{"answers":["4\\,498{,}7"],"expected":{"status":"correct"},"variables":{"a":"3","b":"4498.7","m":"4","q":"1"},"description":"? : 1000 = 4,4987","variationIndex":0},{"answers":["4498{,}7"],"expected":{"status":"unoptimal_form","constraintViolations":["spaces"]},"variables":{"a":"3","b":"4498.7","m":"4","q":"1"},"description":"4498,7 sans espace","variationIndex":0},{"answers":["4\\,498.7"],"expected":{"status":"correct"},"variables":{"a":"3","b":"4498.7","m":"4","q":"1"},"description":"point","variationIndex":0},{"answers":["4{,}498\\,7"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"4498.7","m":"4","q":"1"},"description":"mauvais sens","variationIndex":0}]}$l2n$::jsonb),
