--   ('54468151-387e-425d-bc4f-74bcf1c7fb01'::uuid, $l2n${"title":"Calculer une somme","description":"Sommes d’un nombre à deux chiffres et de dizaines entières","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}}}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"2..8"},{"name":"b","expression":"1..9"},{"name":"c","expression":"1..{{eval:9-a}}"},{"name":"expression1","expression":"{{eval:a*10 + b}} + {{eval:c*10}}"}],"correction":{"steps":["**Ajouter des dizaines entières.** On ajoute ${{eval:c*10}}$, c'est-à-dire ${{eval:((c*10))/10}}$ {{if:((c*10))=10|dizaine|dizaines}} : {{if:(mod(((a*10 + b)),10))*((a*10 + b)-mod(((a*10 + b)),10))>0|on met de côté $\\textcolor{{{color:primary.0}}}{{{eval:mod(((a*10 + b)),10)}}}$ et on calcule $\\textcolor{{{color:primary.0}}}{{{eval:(a*10 + b)-mod(((a*10 + b)),10)}}} + {{eval:c*10}} = \\textcolor{{{color:primary.1}}}{{{eval:(a*10 + b)-mod(((a*10 + b)),10)+(c*10)}}}$.|on compte en dizaines.}}","$$\\begin{align} {{eval:a*10 + b}} + {{eval:c*10}} &= {{if:(mod(((a*10 + b)),10))*((a*10 + b)-mod(((a*10 + b)),10))>0|\\textcolor{{{color:primary.0}}}{{{eval:(a*10 + b)-mod(((a*10 + b)),10)}}} + {{eval:c*10}} + \\textcolor{{{color:primary.0}}}{{{eval:mod(((a*10 + b)),10)}}} \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:(a*10 + b)-mod(((a*10 + b)),10)+(c*10)}}} + {{eval:mod(((a*10 + b)),10)}} \\\\ &= |}}{{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["99"],"expected":{"status":"correct"},"variables":{"a":"6","b":"9","c":"3"},"description":"69+30","variationIndex":0},{"answers":["72"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"9","c":"3"},"description":"dizaines ajoutées aux unités","variationIndex":0}]}$l2n$::jsonb),
