--   ('59b781cc-1e3c-45e7-8b31-9773931129b3'::uuid, $l2n${"title":"Calculer un produit d'entiers","description":"Premiers multiples de $25$ et $50$","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}}}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"expression1","expression":"a*50"}],"correction":{"steps":["{{if:mod((50),100)=0|**Décomposer un facteur.** $50 = \\textcolor{{{color:primary.0}}}{{{eval:(50)/100}}} \\times 100$ : on multiplie par $\\textcolor{{{color:primary.0}}}{{{eval:(50)/100}}}$, puis par $100$.|**Décomposer un facteur.** $50 = \\textcolor{{{color:primary.0}}}{{{eval:(50)/10}}} \\times 10$ : on multiplie par $\\textcolor{{{color:primary.0}}}{{{eval:(50)/10}}}$, puis par $10$.}}","$$\\begin{align} {{a}} \\times 50 &= {{if:mod((50),100)=0|{{a}} \\times \\textcolor{{{color:primary.0}}}{{{eval:(50)/100}}} \\times 100 \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:(a)*(50)/100}}} \\times 100|{{a}} \\times \\textcolor{{{color:primary.0}}}{{{eval:(50)/10}}} \\times 10 \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:(a)*(50)/10}}} \\times 10}} \\\\ &= {{solution}} \\end{align}$$"]}},{"blanks":[{"expectedAnswer":"{{eval:{{expression2}}}}"}],"statement":"Calcule.\n\n$${{expression2}}$$","variables":[{"name":"expression2","expression":"a*25"}],"correction":{"steps":["**Décomposer un facteur.** On décompose $25$ selon ses rangs, $25 = \\textcolor{{{color:primary.0}}}{{{eval:floor(mod((25),100)/10)*10}}} + \\textcolor{{{color:primary.0}}}{{{eval:mod((25),10)}}}$, puis on multiplie chaque morceau par ${{a}}$ et on ajoute les résultats.","$$\\begin{align} {{a}} \\times 25 &= {{a}} \\times \\textcolor{{{color:primary.0}}}{{{eval:floor(mod((25),100)/10)*10}}} + {{a}} \\times \\textcolor{{{color:primary.0}}}{{{eval:mod((25),10)}}} \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:(a)*(floor(mod((25),100)/10)*10)}}} + \\textcolor{{{color:primary.1}}}{{{eval:(a)*(mod((25),10))}}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":{"