--   ('83aa2196-817e-4f49-8fee-d0053a9b9198'::uuid, $l2n${"title":"Calculer une différence (résultat positif)","description":"Soustraire un nombre à un chiffre à un nombre à deux chiffres, avec franchissement de la dizaine","variations":[{"blanks":[{"expectedAnswer":"eval:expression"}],"statement":"$${{expression}}$$","variables":[{"name":"a","expression":"1..9"},{"name":"b","expression":"1..8"},{"name":"c","expression":"{{eval:b+1}}..9"},{"name":"expression","expression":"{{eval:a*10+b}}-{{c}}"}],"correction":{"steps":["{{if:c=9|Retrancher $\\textcolor{{{color:primary.0}}}{9}$, c'est retrancher $\\textcolor{{{color:primary.0}}}{10}$ puis ajouter $\\textcolor{{{color:primary.0}}}{1}$.|On redescend d'abord à la dizaine : on enlève $\\textcolor{{{color:primary.0}}}{{{eval:mod((a*10+b),10)}}}$ à ${{eval:a*10+b}}$ pour arriver à $\\textcolor{{{color:primary.1}}}{{{eval:(a*10+b)-mod((a*10+b),10)}}}$. On décompose donc $\\textcolor{{{color:primary.0}}}{{{c}}}$ en $\\textcolor{{{color:primary.0}}}{{{eval:mod((a*10+b),10)}}} + \\textcolor{{{color:primary.0}}}{{{eval:c-mod((a*10+b),10)}}}$.}}","{{if:c=9|$$\\begin{align} {{eval:a*10+b}} - \\textcolor{{{color:primary.0}}}{9} &= {{eval:a*10+b}} - \\textcolor{{{color:primary.0}}}{10} + \\textcolor{{{color:primary.0}}}{1} \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:(a*10+b)-10}}} + 1 \\\\ &= {{solution}} \\end{align}$$|$$\\begin{align} {{eval:a*10+b}} - \\textcolor{{{color:primary.0}}}{{{c}}} &= {{eval:a*10+b}} - \\textcolor{{{color:primary.0}}}{{{eval:mod((a*10+b),10)}}} - \\textcolor{{{color:primary.0}}}{{{eval:c-mod((a*10+b),10)}}} \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:(a*10+b)-mod((a*10+b),10)}}} - {{eval:c-mod((a*10+b),10)}} \\\\ &= {{solution}} \\end{align}$$}}"]}}],"shared":null,"test_specs":[{"answers":["38"],"expected":{"status":"correct"},"variables":{"a":"4","b":"5","c":"7"},"description":"correct","variationIndex":0},{"answers":["8"],"expected":{"status":"incorrect"},"variables":{"a":"4","b":"5","c":"7"}