--   ('acf15102-533f-49bf-8add-2d6ffd4237aa'::uuid, $l2n${"title":"Calculer une différence (résultat positif)","description":"Une dizaine et un nombre à un chiffre (avec franchissement de la dizaine)","variations":[{"blanks":[{"expectedAnswer":"eval:expression"}],"statement":"$${{expression}}$$","variables":[{"name":"a","expression":"2..9"},{"name":"b","expression":"{{eval:11-a}}..9"},{"name":"expression","expression":"{{eval:a+b}}-{{a}}"}]}],"shared":null,"test_specs":[{"answers":["8"],"expected":{"status":"correct"},"variables":{"a":"5","b":"8"},"description":"correct","variationIndex":0},{"answers":["7"],"expected":{"status":"incorrect"},"variables":{"a":"5","b":"8"},"description":"incorrect","variationIndex":0},{"answers":["5+8-5"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"5","b":"8"},"description":"bad form","variationIndex":0},{"answers":["08"],"expected":{"status":"unoptimal_form","constraintViolations":["zeros"]},"variables":{"a":"5","b":"8"},"description":"unoptimal form","variationIndex":0},{"answers":[""],"expected":{"status":"empty"},"variables":{"a":"5","b":"8"},"description":"empty","variationIndex":0}]}$l2n$::jsonb),
--   ('b100ddb2-e91d-402c-9940-012da8236d1d'::uuid, $l2n${"title":"Calculer une différence","description":"Partie entière et partie décimale à $1$ chiffre (pas de retenue)","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}};d}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"2..8"},{"name":"b","expression":"2..8"},{"name":"c","expression":"a.b"},{"name":"d","expression":"1..{{eval:a-1}}"},{"name":"f","expression":"1..{{eval:b-1}}"},{"name":"g","expression":"d.f"},{"name":"expression1","expression":"c-g"}],"correction":{"steps":["**Soustraire des décimaux.** On soustrait rang par rang : les unités des unités, les dixièmes des dixièmes. Quand on ne peut pas retirer les dixièmes, on échange $1$ unité contre $10$ dixièmes.","Unités : $\\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{d}}} = {{eval:a-d}}$. Dixièmes : $\\textcolor{{{color:primary.0}}}{{{b}}} - \\textcolor{{{color:primary.0}}}{{{f}}} = {{eval:b-f}}$.","$$\\begin{align} {{c}} - {{g}} &= \\left( \\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{d}}} \\right) + \\left( \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} - \\textcolor{{{color:primary.0}}}{{{eval:f/10;d}}} \\right) \\\\ &= {{eval:a-d}} + \\textcolor{{{color:primary.1}}}{{{eval:(b-f)/10;d}}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["2{,}6"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"4","f":"2"},"description":"6,8 − 4,2 = 2,6","variationIndex":0},{"answers":["2.6"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"4","f":"2"},"description":"2.6 au point","variationIndex":0},{"answers":["11"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"8","d":"4","f":"2"},"description":"addition au lieu de soustraction : 11","variationIndex":0}]}$l2n$::jsonb),
