--   ('b9a9048a-d973-47a3-ad5b-acbde2d80a66'::uuid, $l2n${"title":"Calculer une différence","description":"Partie entière à $1$ chiffre et partie décimale à $1$ et $2$ chiffres (pas de retenue)","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}};d}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"2..9"},{"name":"b","expression":"2..9"},{"name":"c","expression":"1..9"},{"name":"d","expression":"{{eval:a+b/10+c/100;d}}"},{"name":"f","expression":"1..{{eval:a-1}}"},{"name":"g","expression":"1..{{eval:b-1}}"},{"name":"h","expression":"f.g"},{"name":"expression1","expression":"d-h"}],"correction":{"steps":["**Soustraire des décimaux.** On soustrait rang par rang : les unités des unités, les dixièmes des dixièmes. Quand on ne peut pas retirer les dixièmes, on échange $1$ unité contre $10$ dixièmes.","Unités : $\\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{f}}} = {{eval:a-f}}$. Dixièmes : $\\textcolor{{{color:primary.0}}}{{{b}}} - \\textcolor{{{color:primary.0}}}{{{g}}} = {{eval:b-g}}$. Centièmes : ${{h}}$ n'en a pas, il reste les $\\textcolor{{{color:primary.0}}}{{{c}}}$ centième{{if:c>1|s|}} de ${{d}}$.","$$\\begin{align} {{d}} - {{h}} &= \\left( \\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{f}}} \\right) + \\left( \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} - \\textcolor{{{color:primary.0}}}{{{eval:g/10;d}}} \\right) + \\textcolor{{{color:primary.0}}}{{{eval:c/100;d}}} \\\\ &= {{eval:a-f}} + \\textcolor{{{color:primary.1}}}{{{eval:(b-g)/10;d}}} + {{eval:c/100;d}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["5{,}29"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"9","f":"2","g":"7"},"description":"7,99 − 2,7 = 5,29","variationIndex":0},{"answers":["5.29"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"9","f":"2","g":"7"},"description":"5.29 au point","variationIndex":0},{"answers":["7{,}72"],"expected":{"status":"incorrect"},"variables":{"a":"7","b":"9","c":"9","f":"2","g":"7"},"description":"alignement à droite : 7,72","variationIndex":0}]}$l2n$::jsonb),
--   ('bcd7e907-22f5-4f0f-a8bd-8e3ea60132e0'::uuid, $l2n${"title":"Trouver le double","description":"Nombre inférieur à $10$","variations":[{"blanks":[{"expectedAnswer":"{{eval:2*a}}"}],"statement":"Quel est le double de ${{a}}$ ?\n\nLe double de ${{a}}$ est $?$.","variables":[{"name":"a","expression":"0..9"}],"correction":{"steps":["Le double de ${{a}}$ est ${{eval:2*a}}$ car ${{a}} + {{a}} = {{eval:2*a}}$."]}}],"shared":null,"test_specs":[{"answers":["14"],"expected":{"status":"correct"},"variables":{"a":"7"},"description":"double de 7 → 14","variationIndex":0},{"answers":["0"],"expected":{"status":"correct"},"variables":{"a":"0"},"description":"double de 0 → 0","variationIndex":0},{"answers":["9"],"expected":{"status":"incorrect"},"variables":{"a":"7"},"description":"double de 7 : 7+2 refusé","variationIndex":0}]}$l2n$::jsonb),
--   ('bd760867-7303-4ac8-87eb-724fb5994cab'::uuid, $l2n${"title":"Ecrire un grand nombre entier avec des espaces","description":"Jusqu'à 7 chiffres","variations":[{"blanks":[{"prefilled":"expression","removeSpaces":true,"expectedAnswer":"expression"}],"statement":"Réécris en espaçant correctement les chiffres.\n\n$$?$$","variables":[{"name":"a","expression":"4..7"},{"name":"expression","expression":"digits:a"}],"correction":{"steps":["**Écrire un grand nombre.** On sépare les chiffres par groupes de trois **en partant de la droite** (des unités) : classe des unités, classe des milliers, classe des millions, classe des milliards. Le groupe de gauche peut avoir un, deux ou trois chiffres.","On part du chiffre des unités de ${{expression}}$ et on compte les chiffres trois par trois vers la gauche ; on laisse un espace entre deux groupes.","$$\\begin{align} {{expression}} &= {{if:a>12|{{eval:floor(round(floor(expression/1000000000)-1000*floor(expression/1000000000000))/100)}}{{eval:mod((floor(round(floor(expression/1000000000)-1000*floor(expression/1000000000000))/10)),10)}}{{eval:mod((round(floor(expression/1000000000)-1000*floor(expression/1000000000000))),10)}}\\,|{{if:a>9|{{eval:round(floor(expression/1000000000)-1000*floor(expression/1000000000000))}}\\,|}}}}{{if:a>9|{{eval:floor(round(floor(expression/1000000)-1000*floor(expression/1000000000))/100)}}{{eval:mod((floor(round(floor(expression/1000000)-1000*floor(expression/1000000000))/10)),10)}}{{eval:mod((round(floor(expression/1000000)-1000*floor(expression/1000000000))),10)}}\\,|{{if:a>6|{{eval:round(floor(expression/1000000)-1000*floor(expression/1000000000))}}\\,|}}}}{{if:a>6|{{eval:floor(round(floor(expression/1000)-1000*floor(expression/1000000))/100)}}{{eval:mod((floor(round(floor(expression/1000)-1000*floor(expression/1000000))/10)),10)}}{{eval:mod((round(floor(expression/1000)-1000*floor(expression/1000000))),10)}}\\,|{{if:a>3|{{eval:round(floor(expression/1000)-1000*floor(expression/1000000))}}\\,|}}}}{{if:a>3|\\textcolor{{{color:primary.0}}}{{{eval:floor(round(expression-1000*floor(expression/1000))/100)}}{{eval:mod((floor(round(expression-1000*floor(expression/1000))/10)),10)}}{{eval:mod((round(expression-1000*floor(expression/1000))),10)}}}|{{if:a>0|\\textcolor{{{color:primary.0}}}{{{eval:round(expression-1000*floor(expression/1000))}}}|}}}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["1\\,234\\,567"],"expected":{"status":"correct"},"variables":{"a":"7","expression":"1234567"},"description":"7 chiffres bien espacés","variationIndex":0},{"answers":["1234567"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"7","expression":"1234567"},"description":"7 chiffres sans espace","variationIndex":0},{"answers":["1\\,234"],"expected":{"status":"correct"},"variables":{"a":"4","expression":"1234"},"description":"4 chiffres (borne basse)","variationIndex":0},{"answers":["1234"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"4","expression":"1234"},"description":"4 chiffres sans espace","variationIndex":0}]}$l2n$::jsonb),
