insert into _l2n_modeles values ('0dd3de90-10fc-485b-a961-343b01a84cee', $l2n$Nombres et calculs$l2n$, $l2n$Entiers : numération$l2n$, $l2n$écritures$l2n$, array['CM2'], 'CM2', 'CM2-003',
  $l2n${"title":"Ecrire un grand nombre entier avec des espaces","description":"Jusqu'à 10 chiffres","variations":[{"blanks":[{"prefilled":"expression","removeSpaces":true,"expectedAnswer":"expression"}],"statement":"Réécris en espaçant correctement les chiffres.\n\n$$?$$","variables":[{"name":"a","expression":"4..10"},{"name":"expression","expression":"digits:a"}],"correction":{"steps":["**Écrire un grand nombre.** On sépare les chiffres par groupes de trois **en partant de la droite** (des unités) : classe des unités, classe des milliers, classe des millions, classe des milliards. Le groupe de gauche peut avoir un, deux ou trois chiffres.","On part du chiffre des unités de ${{expression}}$ et on compte les chiffres trois par trois vers la gauche ; on laisse un espace entre deux groupes.","$$\\begin{align} {{expression}} &= {{if:a>12|{{eval:floor(round(floor(expression/1000000000)-1000*floor(expression/1000000000000))/100)}}{{eval:mod((floor(round(floor(expression/1000000000)-1000*floor(expression/1000000000000))/10)),10)}}{{eval:mod((round(floor(expression/1000000000)-1000*floor(expression/1000000000000))),10)}}\\,|{{if:a>9|{{eval:round(floor(expression/1000000000)-1000*floor(expression/1000000000000))}}\\,|}}}}{{if:a>9|{{eval:floor(round(floor(expression/1000000)-1000*floor(expression/1000000000))/100)}}{{eval:mod((floor(round(floor(expression/1000000)-1000*floor(expression/1000000000))/10)),10)}}{{eval:mod((round(floor(expression/1000000)-1000*floor(expression/1000000000))),10)}}\\,|{{if:a>6|{{eval:round(floor(expression/1000000)-1000*floor(expression/1000000000))}}\\,|}}}}{{if:a>6|{{eval:floor(round(floor(expression/1000)-1000*floor(expression/1000000))/100)}}{{eval:mod((floor(round(floor(expression/1000)-1000*floor(expression/1000000))/10)),10)}}{{eval:mod((round(floor(expression/1000)-1000*floor(expression/1000000))),10)}}\\,|{{if:a>3|{{eval:round(floor(expression/1000)-1000*floor(expression/1000000))}}\\,|}}}}{{if:a>3|\\textcolor{{{color:primary.0}}}{{{eval:floor(round(expression-1000*floor(expression/1000))/100)}}{{eval:mod((floor(round(expression-1000*floor(expression/1000))/10)),10)}}{{eval:mod((round(expression-1000*floor(expression/1000))),10)}}}|{{if:a>0|\\textcolor{{{color:primary.0}}}{{{eval:round(expression-1000*floor(expression/1000))}}}|}}}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["1\\,234\\,567\\,890"],"expected":{"status":"correct"},"variables":{"a":"10","expression":"1234567890"},"description":"10 chiffres bien espacés (borne haute)","variationIndex":0},{"answers":["1234567890"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"10","expression":"1234567890"},"description":"10 chiffres sans espace","variationIndex":0},{"answers":["1\\,234\\,567\\,891"],"expected":{"status":"incorrect"},"variables":{"a":"10","expression":"1234567890"},"description":"chiffre modifié","variationIndex":0},{"answers":["5\\,000"],"expected":{"status":"correct"},"variables":{"a":"4","expression":"5000"},"description":"4 chiffres (borne basse)","variationIndex":0},{"answers":["5000"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"4","expression":"5000"},"description":"4 chiffres sans espace","variationIndex":0}]}$l2n$::jsonb,
