oor(round(expression-1000*floor(expression/1000))/100)}}{{eval:mod((floor(round(expression-1000*floor(expression/1000))/10)),10)}}{{eval:mod((round(expression-1000*floor(expression/1000))),10)}}}|{{if:a>0|\\textcolor{{{color:primary.0}}}{{{eval:round(expression-1000*floor(expression/1000))}}}|}}}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["123\\,456\\,789"],"expected":{"status":"correct"},"variables":{"a":"9","expression":"123456789"},"description":"9 chiffres bien espacés (borne haute)","variationIndex":0},{"answers":["123456789"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"9","expression":"123456789"},"description":"9 chiffres sans espace","variationIndex":0},{"answers":["123\\,456\\,788"],"expected":{"status":"incorrect"},"variables":{"a":"9","expression":"123456789"},"description":"chiffre modifié","variationIndex":0},{"answers":["5\\,000"],"expected":{"status":"correct"},"variables":{"a":"4","expression":"5000"},"description":"4 chiffres (borne basse)","variationIndex":0},{"answers":["5000"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"4","expression":"5000"},"description":"4 chiffres sans espace","variationIndex":0}]}$l2n$::jsonb);
