insert into _l2n_modeles values ('201b17f0-a12e-4772-abc4-fe75cb81ef44', $l2n$Nombres et calculs$l2n$, $l2n$Entiers : addition et soustraction$l2n$, $l2n$calcul astucieux$l2n$, array['CP'], 'CP', 'CP-083',
  $l2n${"title":"Calculer une différence (résultat positif)","description":"Soustraire des dizaines entières à un nombre","variations":[{"blanks":[{"expectedAnswer":"eval:expression"}],"statement":"$${{expression}}$$","variables":[{"name":"a","expression":"1..8"},{"name":"b","expression":"{{eval:a+1}}..9"},{"name":"c","expression":"0..9"},{"name":"expression","expression":"{{eval:b*10+c}}-{{eval:a*10}}"}],"correction":{"steps":["**Retrancher des dizaines entières.** On retranche ${{eval:a*10}}$, c'est-à-dire ${{eval:((a*10))/10}}$ {{if:((a*10))=10|dizaine|dizaines}} : {{if:(mod(((b*10+c)),10))*((b*10+c)-mod(((b*10+c)),10))>0|on met de côté $\\textcolor{{{color:primary.0}}}{{{eval:mod(((b*10+c)),10)}}}$ et on calcule $\\textcolor{{{color:primary.0}}}{{{eval:(b*10+c)-mod(((b*10+c)),10)}}} - {{eval:a*10}} = \\textcolor{{{color:primary.1}}}{{{eval:(b*10+c)-mod(((b*10+c)),10)-(a*10)}}}$.|on compte en dizaines.}}","$$\\begin{align} {{eval:b*10+c}} - {{eval:a*10}} &= {{if:(mod(((b*10+c)),10))*((b*10+c)-mod(((b*10+c)),10))>0|\\textcolor{{{color:primary.0}}}{{{eval:(b*10+c)-mod(((b*10+c)),10)}}} - {{eval:a*10}} + \\textcolor{{{color:primary.0}}}{{{eval:mod(((b*10+c)),10)}}} \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:(b*10+c)-mod(((b*10+c)),10)-(a*10)}}} + {{eval:mod(((b*10+c)),10)}} \\\\ &= |}}{{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["32"],"expected":{"status":"correct"},"variables":{"a":"4","b":"7","c":"2"},"description":"correct","variationIndex":0},{"answers":["33"],"expected":{"status":"incorrect"},"variables":{"a":"4","b":"7","c":"2"},"description":"incorrect","variationIndex":0},{"answers":["72-40"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"4","b":"7","c":"2"},"description":"bad form","variationIndex":0},{"answers":["032"],"expected":{"status":"unoptimal_form","constraintViolations":["zeros"]},"variables":{"a":"4","b":"7","c":"2"},"description":"unoptimal form (zeros)","variationIndex":0},{"answers":[""],"expected":{"status":"empty"},"variables":{"a":"4","b":"7","c":"2"},"description":"empty","variationIndex":0}]}$l2n$::jsonb,
