insert into _l2n_modeles values ('3bbe92f2-84f0-487f-9ca1-2077248a313b', $l2n$Nombres et calculs$l2n$, $l2n$Décimaux : calculs$l2n$, $l2n$addition$l2n$, array['CM1'], 'CM1', 'CM1-039',
  $l2n${"title":"Calculer une somme","description":"Partie entière et partie décimale à $1$ chiffre (pas de retenue)","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}};d}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"1..8"},{"name":"b","expression":"1..8"},{"name":"c","expression":"a.b"},{"name":"d","expression":"1..{{eval:9-a}}"},{"name":"f","expression":"1..{{eval:9-b}}"},{"name":"g","expression":"d.f"},{"name":"expression1","expression":"c+g"}],"correction":{"steps":["**Additionner des décimaux.** On additionne rang par rang : les unités avec les unités, les dixièmes avec les dixièmes, les centièmes avec les centièmes. $10$ dixièmes font $1$ unité.","Unités : $\\textcolor{{{color:primary.0}}}{{{a}}} + \\textcolor{{{color:primary.0}}}{{{d}}} = {{eval:a+d}}$. Dixièmes : $\\textcolor{{{color:primary.0}}}{{{b}}} + \\textcolor{{{color:primary.0}}}{{{f}}} = {{eval:b+f}}$ dixièmes{{if:b+f>=10|, soit $\\textcolor{{{color:primary.1}}}{1}$ unité et ${{eval:b+f-10}}$ dixième{{if:b+f-10>1|s|}}|}}.","$$\\begin{align} {{c}} + {{g}} &= \\left( \\textcolor{{{color:primary.0}}}{{{a}}} + \\textcolor{{{color:primary.0}}}{{{d}}} \\right) + \\left( \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} + \\textcolor{{{color:primary.0}}}{{{eval:f/10;d}}} \\right) \\\\ &= {{eval:a+d}} + \\textcolor{{{color:primary.1}}}{{{eval:(b+f)/10;d}}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["8{,}9"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"2","f":"1"},"description":"6,8 + 2,1 = 8,9","variationIndex":0},{"answers":["8.9"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"2","f":"1"},"description":"8.9 au point","variationIndex":0},{"answers":["8{,}8"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"8","d":"2","f":"1"},"description":"erreur : 8,8","variationIndex":0},{"answers":["89"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"8","d":"2","f":"1"},"description":"réponse 89 (virgule oubliée)","variationIndex":0}]}$l2n$::jsonb,
  $l2n${"title":"Calculer une somme","description":"Partie entière et partie décimale à $1$ chiffre (pas de retenue)","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}};d}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"1..8"},{"name":"b","expression":"1..8"},{"name":"c","expression":"a.b"},{"name":"d","expression":"1..{{eval:9-a}}"},{"name":"expression1","expression":"c+d"}],"correction":{"steps":["**Additionner des décimaux.** On additionne rang par rang : les unités avec les unités, les dixièmes avec les dixièmes, les centièmes avec les centièmes. $10$ dixièmes font $1$ unité.","Unités : $\\textcolor{{{color:primary.0}}}{{{a}}} + \\textcolor{{{color:primary.0}}}{{{d}}} = {{eval:a+d}}$. Dixièmes : ${{d}}$ n'en a pas, il reste les $\\textcolor{{{color:primary.0}}}{{{b}}}$ dixième{{if:b>1|s|}} de ${{c}}$.","$$\\begin{align} {{c}} + {{d}} &= \\left( \\textcolor{{{color:primary.0}}}{{{a}}} + \\textcolor{{{color:primary.0}}}{{{d}}} \\right) + \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:a+d}}} + {{eval:b/10;d}} \\\\ &= {{solution}} \\end{align}$$"]}},{"blanks":[{"expectedAnswer":"{{eval:{{expression2}};d}}"}],"statement":"Calcule.\n\n$${{expression2}}$$","variables":[{"name":"a","expression":"1..8"},{"name":"b","expression":"1..8"},{"name":"c","expression":"a.b"},{"name":"f","expression":"1..{{eval:9-b}}"},{"name":"g","expression":"0.f"},{"name":"expression2","expression":"c+g"}],"correction":{"steps":["**Additionner des décimaux.** On additionne rang par rang : les unités avec les unités, les dixièmes avec les dixièmes, les centièmes avec les centièmes. $10$ dixièmes font $1$ unité.","Dixièmes : $\\textcolor{{{color:primary.0}}}{{{b}}} + \\textcolor{{{color:primary.0}}}{{{f}}} = {{eval:b+f}}$ dixièmes. Unités : ${{g}}$ n'en a pas, il reste les $\\textcolor{{{color:primary.0}}}{{{a}}}$ unité{{if:a>1|s|}} de ${{c}}$.","$$\\begin{align} {{c}} + {{g}} &= \\textcolor{{{color:primary.0}}}{{{a}}} + \\left( \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} + \\textcolor{{{color:primary.0}}}{{{eval:f/10;d}}} \\right) \\\\ &= {{a}} + \\textcolor{{{color:primary.1}}}{{{eval:(b+f)/10;d}}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["8{,}8"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"2"},"description":"6,8 + 2 = 8,8","variationIndex":0},{"answers":["8.8"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"2"},"description":"8.8 au point","variationIndex":0},{"answers":["6{,}10"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"8","d":"2"},"description":"ajout aux dixièmes : 6,10","variationIndex":0},{"answers":["6{,}9"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","f":"1"},"description":"6,8 + 0,1 = 6,9","variationIndex":1},{"answers":["7{,}8"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"8","f":"1"},"description":"ajout aux unités : 7,8","variationIndex":1}]}$l2n$::jsonb);
