insert into _l2n_modeles values ('b100ddb2-e91d-402c-9940-012da8236d1d', $l2n$Nombres et calculs$l2n$, $l2n$Décimaux : calculs$l2n$, $l2n$soustraction$l2n$, array['CM1'], 'CM1', 'CM1-133',
  $l2n${"title":"Calculer une différence","description":"Partie entière et partie décimale à $1$ chiffre (pas de retenue)","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}};d}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"2..8"},{"name":"b","expression":"2..8"},{"name":"c","expression":"a.b"},{"name":"d","expression":"1..{{eval:a-1}}"},{"name":"f","expression":"1..{{eval:b-1}}"},{"name":"g","expression":"d.f"},{"name":"expression1","expression":"c-g"}],"correction":{"steps":["**Soustraire des décimaux.** On soustrait rang par rang : les unités des unités, les dixièmes des dixièmes. Quand on ne peut pas retirer les dixièmes, on échange $1$ unité contre $10$ dixièmes.","Unités : $\\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{d}}} = {{eval:a-d}}$. Dixièmes : $\\textcolor{{{color:primary.0}}}{{{b}}} - \\textcolor{{{color:primary.0}}}{{{f}}} = {{eval:b-f}}$.","$$\\begin{align} {{c}} - {{g}} &= \\left( \\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{d}}} \\right) + \\left( \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} - \\textcolor{{{color:primary.0}}}{{{eval:f/10;d}}} \\right) \\\\ &= {{eval:a-d}} + \\textcolor{{{color:primary.1}}}{{{eval:(b-f)/10;d}}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["2{,}6"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"4","f":"2"},"description":"6,8 − 4,2 = 2,6","variationIndex":0},{"answers":["2.6"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"4","f":"2"},"description":"2.6 au point","variationIndex":0},{"answers":["11"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"8","d":"4","f":"2"},"description":"addition au lieu de soustraction : 11","variationIndex":0}]}$l2n$::jsonb,
  $l2n${"title":"Calculer une différence","description":"Partie entière et partie décimale à $1$ chiffre (pas de retenue)","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}};d}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"2..8"},{"name":"b","expression":"2..8"},{"name":"c","expression":"a.b"},{"name":"d","expression":"1..{{eval:a-1}}"},{"name":"expression1","expression":"c-d"}],"correction":{"steps":["**Soustraire des décimaux.** On soustrait rang par rang : les unités des unités, les dixièmes des dixièmes. Quand on ne peut pas retirer les dixièmes, on échange $1$ unité contre $10$ dixièmes.","Unités : $\\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{d}}} = {{eval:a-d}}$. Dixièmes : ${{d}}$ n'en a pas, il reste les $\\textcolor{{{color:primary.0}}}{{{b}}}$ dixièmes de ${{c}}$.","$$\\begin{align} {{c}} - {{d}} &= \\left( \\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{d}}} \\right) + \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:a-d}}} + {{eval:b/10;d}} \\\\ &= {{solution}} \\end{align}$$"]}},{"blanks":[{"expectedAnswer":"{{eval:{{expression2}};d}}"}],"statement":"Calcule.\n\n$${{expression2}}$$","variables":[{"name":"a","expression":"2..8"},{"name":"b","expression":"2..8"},{"name":"c","expression":"a.b"},{"name":"f","expression":"1..{{eval:b-1}}"},{"name":"g","expression":"0.f"},{"name":"expression2","expression":"c-g"}],"correction":{"steps":["**Soustraire des décimaux.** On soustrait rang par rang : les unités des unités, les dixièmes des dixièmes. Quand on ne peut pas retirer les dixièmes, on échange $1$ unité contre $10$ dixièmes.","Dixièmes : $\\textcolor{{{color:primary.0}}}{{{b}}} - \\textcolor{{{color:primary.0}}}{{{f}}} = {{eval:b-f}}$. Unités : ${{g}}$ n'en a pas, il reste les $\\textcolor{{{color:primary.0}}}{{{a}}}$ unités de ${{c}}$.","$$\\begin{align} {{c}} - {{g}} &= \\textcolor{{{color:primary.0}}}{{{a}}} + \\left( \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} - \\textcolor{{{color:primary.0}}}{{{eval:f/10;d}}} \\right) \\\\ &= {{a}} + \\textcolor{{{color:primary.1}}}{{{eval:(b-f)/10;d}}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["2{,}8"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"4"},"description":"6,8 − 4 = 2,8","variationIndex":0},{"answers":["2.8"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","d":"4"},"description":"2.8 au point","variationIndex":0},{"answers":["10{,}8"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"8","d":"4"},"description":"addition au lieu de soustraction : 10,8","variationIndex":0},{"answers":["6{,}6"],"expected":{"status":"correct"},"variables":{"a":"6","b":"8","f":"2"},"description":"6,8 − 0,2 = 6,6","variationIndex":1},{"answers":["4{,}8"],"expected":{"status":"incorrect"},"variables":{"a":"6","b":"8","f":"2"},"description":"retrait aux unités : 4,8","variationIndex":1}]}$l2n$::jsonb);
