insert into _l2n_modeles values ('b9a9048a-d973-47a3-ad5b-acbde2d80a66', $l2n$Nombres et calculs$l2n$, $l2n$Décimaux : calculs$l2n$, $l2n$soustraction$l2n$, array['CM1'], 'CM1', 'CM1-133',
  $l2n${"title":"Calculer une différence","description":"Partie entière à $1$ chiffre et partie décimale à $1$ et $2$ chiffres (pas de retenue)","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}};d}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"2..9"},{"name":"b","expression":"2..9"},{"name":"c","expression":"1..9"},{"name":"d","expression":"{{eval:a+b/10+c/100;d}}"},{"name":"f","expression":"1..{{eval:a-1}}"},{"name":"g","expression":"1..{{eval:b-1}}"},{"name":"h","expression":"f.g"},{"name":"expression1","expression":"d-h"}],"correction":{"steps":["**Soustraire des décimaux.** On soustrait rang par rang : les unités des unités, les dixièmes des dixièmes. Quand on ne peut pas retirer les dixièmes, on échange $1$ unité contre $10$ dixièmes.","Unités : $\\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{f}}} = {{eval:a-f}}$. Dixièmes : $\\textcolor{{{color:primary.0}}}{{{b}}} - \\textcolor{{{color:primary.0}}}{{{g}}} = {{eval:b-g}}$. Centièmes : ${{h}}$ n'en a pas, il reste les $\\textcolor{{{color:primary.0}}}{{{c}}}$ centième{{if:c>1|s|}} de ${{d}}$.","$$\\begin{align} {{d}} - {{h}} &= \\left( \\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{f}}} \\right) + \\left( \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} - \\textcolor{{{color:primary.0}}}{{{eval:g/10;d}}} \\right) + \\textcolor{{{color:primary.0}}}{{{eval:c/100;d}}} \\\\ &= {{eval:a-f}} + \\textcolor{{{color:primary.1}}}{{{eval:(b-g)/10;d}}} + {{eval:c/100;d}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["5{,}29"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"9","f":"2","g":"7"},"description":"7,99 − 2,7 = 5,29","variationIndex":0},{"answers":["5.29"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"9","f":"2","g":"7"},"description":"5.29 au point","variationIndex":0},{"answers":["7{,}72"],"expected":{"status":"incorrect"},"variables":{"a":"7","b":"9","c":"9","f":"2","g":"7"},"description":"alignement à droite : 7,72","variationIndex":0}]}$l2n$::jsonb,
  $l2n${"title":"Calculer une différence","description":"Partie entière à $1$ chiffre et partie décimale à $1$ et $2$ chiffres (pas de retenue)","variations":[{"blanks":[{"expectedAnswer":"{{eval:{{expression1}};d}}"}],"statement":"Calcule.\n\n$${{expression1}}$$","variables":[{"name":"a","expression":"2..9"},{"name":"b","expression":"2..9"},{"name":"c","expression":"1..9"},{"name":"d","expression":"{{eval:a+b/10+c/100;d}}"},{"name":"f","expression":"1..{{eval:a-1}}"},{"name":"expression1","expression":"d-f"}],"correction":{"steps":["**Soustraire des décimaux.** On soustrait rang par rang : les unités des unités, les dixièmes des dixièmes. Quand on ne peut pas retirer les dixièmes, on échange $1$ unité contre $10$ dixièmes.","Unités : $\\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{f}}} = {{eval:a-f}}$. Dixièmes et centièmes : ${{f}}$ n'en a pas, ceux de ${{d}}$ ne changent pas.","$$\\begin{align} {{d}} - {{f}} &= \\left( \\textcolor{{{color:primary.0}}}{{{a}}} - \\textcolor{{{color:primary.0}}}{{{f}}} \\right) + \\textcolor{{{color:primary.0}}}{{{eval:b/10+c/100;d}}} \\\\ &= \\textcolor{{{color:primary.1}}}{{{eval:a-f}}} + {{eval:b/10+c/100;d}} \\\\ &= {{solution}} \\end{align}$$"]}},{"blanks":[{"expectedAnswer":"{{eval:{{expression2}};d}}"}],"statement":"Calcule.\n\n$${{expression2}}$$","variables":[{"name":"a","expression":"2..9"},{"name":"b","expression":"2..9"},{"name":"c","expression":"1..9"},{"name":"d","expression":"{{eval:a+b/10+c/100;d}}"},{"name":"g","expression":"1..{{eval:b-1}}"},{"name":"h","expression":"0.g"},{"name":"expression2","expression":"d-h"}],"correction":{"steps":["**Soustraire des décimaux.** On soustrait rang par rang : les unités des unités, les dixièmes des dixièmes. Quand on ne peut pas retirer les dixièmes, on échange $1$ unité contre $10$ dixièmes.","Dixièmes : $\\textcolor{{{color:primary.0}}}{{{b}}} - \\textcolor{{{color:primary.0}}}{{{g}}} = {{eval:b-g}}$. Unités et centièmes : ${{h}}$ n'en a pas, ceux de ${{d}}$ ne changent pas.","$$\\begin{align} {{d}} - {{h}} &= \\textcolor{{{color:primary.0}}}{{{a}}} + \\left( \\textcolor{{{color:primary.0}}}{{{eval:b/10;d}}} - \\textcolor{{{color:primary.0}}}{{{eval:g/10;d}}} \\right) + \\textcolor{{{color:primary.0}}}{{{eval:c/100;d}}} \\\\ &= {{a}} + \\textcolor{{{color:primary.1}}}{{{eval:(b-g)/10;d}}} + {{eval:c/100;d}} \\\\ &= {{solution}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["5{,}99"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"9","f":"2"},"description":"7,99 − 2 = 5,99","variationIndex":0},{"answers":["5.99"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"9","f":"2"},"description":"5.99 au point","variationIndex":0},{"answers":["7{,}97"],"expected":{"status":"incorrect"},"variables":{"a":"7","b":"9","c":"9","f":"2"},"description":"alignement à droite : 7,97","variationIndex":0},{"answers":["7{,}29"],"expected":{"status":"correct"},"variables":{"a":"7","b":"9","c":"9","g":"7"},"description":"7,99 − 0,7 = 7,29","variationIndex":1},{"answers":["7{,}92"],"expected":{"status":"incorrect"},"variables":{"a":"7","b":"9","c":"9","g":"7"},"description":"alignement à droite : 7,92","variationIndex":1}]}$l2n$::jsonb);
