  $l2n${"title":"Trouver le double","description":"Nombre inférieur à $10$","variations":[{"blanks":[{"expectedAnswer":"{{eval:2*a}}"}],"statement":"Quel est le double de ${{a}}$ ?\n\nLe double de ${{a}}$ est $?$.","variables":[{"name":"a","expression":"0..9"}],"correction":{"steps":["Le double de ${{a}}$ est ${{eval:2*a}}$ car ${{a}} + {{a}} = {{eval:2*a}}$."]}}],"shared":null,"test_specs":[{"answers":["14"],"expected":{"status":"correct"},"variables":{"a":"7"},"description":"double de 7 → 14","variationIndex":0},{"answers":["0"],"expected":{"status":"correct"},"variables":{"a":"0"},"description":"double de 0 → 0","variationIndex":0},{"answers":["9"],"expected":{"status":"incorrect"},"variables":{"a":"7"},"description":"double de 7 : 7+2 refusé","variationIndex":0}]}$l2n$::jsonb,
