insert into _l2n_modeles values ('bd760867-7303-4ac8-87eb-724fb5994cab', $l2n$Nombres et calculs$l2n$, $l2n$Entiers : numération$l2n$, $l2n$écritures$l2n$, array['CM1'], 'CM1', 'CM1-006',
  $l2n${"title":"Ecrire un grand nombre entier avec des espaces","description":"Jusqu'à 7 chiffres","variations":[{"blanks":[{"prefilled":"expression","removeSpaces":true,"expectedAnswer":"expression"}],"statement":"Réécris en espaçant correctement les chiffres.\n\n$$?$$","variables":[{"name":"a","expression":"4..7"},{"name":"expression","expression":"digits:a"}],"correction":{"steps":["**Écrire un grand nombre.** On sépare les chiffres par groupes de trois **en partant de la droite** (des unités) : classe des unités, classe des milliers, classe des millions, classe des milliards. Le groupe de gauche peut avoir un, deux ou trois chiffres.","On part du chiffre des unités de ${{expression}}$ et on compte les chiffres trois par trois vers la gauche ; on laisse un espace entre deux groupes.","$$\\begin{align} {{expression}} &= {{if:a>12|{{eval:floor(round(floor(expression/1000000000)-1000*floor(expression/1000000000000))/100)}}{{eval:mod((floor(round(floor(expression/1000000000)-1000*floor(expression/1000000000000))/10)),10)}}{{eval:mod((round(floor(expression/1000000000)-1000*floor(expression/1000000000000))),10)}}\\,|{{if:a>9|{{eval:round(floor(expression/1000000000)-1000*floor(expression/1000000000000))}}\\,|}}}}{{if:a>9|{{eval:floor(round(floor(expression/1000000)-1000*floor(expression/1000000000))/100)}}{{eval:mod((floor(round(floor(expression/1000000)-1000*floor(expression/1000000000))/10)),10)}}{{eval:mod((round(floor(expression/1000000)-1000*floor(expression/1000000000))),10)}}\\,|{{if:a>6|{{eval:round(floor(expression/1000000)-1000*floor(expression/1000000000))}}\\,|}}}}{{if:a>6|{{eval:floor(round(floor(expression/1000)-1000*floor(expression/1000000))/100)}}{{eval:mod((floor(round(floor(expression/1000)-1000*floor(expression/1000000))/10)),10)}}{{eval:mod((round(floor(expression/1000)-1000*floor(expression/1000000))),10)}}\\,|{{if:a>3|{{eval:round(floor(expression/1000)-1000*floor(expression/1000000))}}\\,|}}}}{{if:a>3|\\textcolor{{{color:primary.0}}}{{{eval:floor(round(expression-1000*floor(expression/1000))/100)}}{{eval:mod((floor(round(expression-1000*floor(expression/1000))/10)),10)}}{{eval:mod((round(expression-1000*floor(expression/1000))),10)}}}|{{if:a>0|\\textcolor{{{color:primary.0}}}{{{eval:round(expression-1000*floor(expression/1000))}}}|}}}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["1\\,234\\,567"],"expected":{"status":"correct"},"variables":{"a":"7","expression":"1234567"},"description":"7 chiffres bien espacés","variationIndex":0},{"answers":["1234567"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"7","expression":"1234567"},"description":"7 chiffres sans espace","variationIndex":0},{"answers":["1\\,234"],"expected":{"status":"correct"},"variables":{"a":"4","expression":"1234"},"description":"4 chiffres (borne basse)","variationIndex":0},{"answers":["1234"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"4","expression":"1234"},"description":"4 chiffres sans espace","variationIndex":0}]}$l2n$::jsonb,
  $l2n${"title":"Ecrire un grand nombre entier avec des espaces","description":"Jusqu'à 6 chiffres","variations":[{"blanks":[{"prefilled":"expression","removeSpaces":true,"expectedAnswer":"expression"}],"statement":"Réécris en espaçant correctement les chiffres.\n\n$$?$$","variables":[{"name":"a","expression":"4..6"},{"name":"expression","expression":"digits:a"}],"correction":{"steps":["**Écrire un grand nombre.** On sépare les chiffres par groupes de trois **en partant de la droite** (des unités) : classe des unités, classe des milliers, classe des millions, classe des milliards. Le groupe de gauche peut avoir un, deux ou trois chiffres.","On part du chiffre des unités de ${{expression}}$ et on compte les chiffres trois par trois vers la gauche ; on laisse un espace entre deux groupes.","$$\\begin{align} {{expression}} &= {{if:a>12|{{eval:floor(round(floor(expression/1000000000)-1000*floor(expression/1000000000000))/100)}}{{eval:mod((floor(round(floor(expression/1000000000)-1000*floor(expression/1000000000000))/10)),10)}}{{eval:mod((round(floor(expression/1000000000)-1000*floor(expression/1000000000000))),10)}}\\,|{{if:a>9|{{eval:round(floor(expression/1000000000)-1000*floor(expression/1000000000000))}}\\,|}}}}{{if:a>9|{{eval:floor(round(floor(expression/1000000)-1000*floor(expression/1000000000))/100)}}{{eval:mod((floor(round(floor(expression/1000000)-1000*floor(expression/1000000000))/10)),10)}}{{eval:mod((round(floor(expression/1000000)-1000*floor(expression/1000000000))),10)}}\\,|{{if:a>6|{{eval:round(floor(expression/1000000)-1000*floor(expression/1000000000))}}\\,|}}}}{{if:a>6|{{eval:floor(round(floor(expression/1000)-1000*floor(expression/1000000))/100)}}{{eval:mod((floor(round(floor(expression/1000)-1000*floor(expression/1000000))/10)),10)}}{{eval:mod((round(floor(expression/1000)-1000*floor(expression/1000000))),10)}}\\,|{{if:a>3|{{eval:round(floor(expression/1000)-1000*floor(expression/1000000))}}\\,|}}}}{{if:a>3|\\textcolor{{{color:primary.0}}}{{{eval:floor(round(expression-1000*floor(expression/1000))/100)}}{{eval:mod((floor(round(expression-1000*floor(expression/1000))/10)),10)}}{{eval:mod((round(expression-1000*floor(expression/1000))),10)}}}|{{if:a>0|\\textcolor{{{color:primary.0}}}{{{eval:round(expression-1000*floor(expression/1000))}}}|}}}} \\end{align}$$"]}}],"shared":null,"test_specs":[{"answers":["123\\,456"],"expected":{"status":"correct"},"variables":{"a":"6","expression":"123456"},"description":"6 chiffres bien espacés (borne haute)","variationIndex":0},{"answers":["123456"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"6","expression":"123456"},"description":"6 chiffres sans espace","variationIndex":0},{"answers":["1\\,234"],"expected":{"status":"correct"},"variables":{"a":"4","expression":"1234"},"description":"4 chiffres (borne basse)","variationIndex":0},{"answers":["1234"],"expected":{"status":"bad_form","constraintViolations":["spaces","form"]},"variables":{"a":"4","expression":"1234"},"description":"4 chiffres sans espace","variationIndex":0}]}$l2n$::jsonb);
